import{_ as s,o as a,c as i,ai as t}from"./chunks/framework.Ci0kozOl.js";const u=JSON.parse('{"title":"Upgrade Guide","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/prologue/upgrade-guide.md","filePath":"2.1/prologue/upgrade-guide.md","lastUpdated":1778854311000}'),n={name:"2.1/prologue/upgrade-guide.md"};function o(r,e,l,p,d,h){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="upgrade-guide" tabindex="-1">Upgrade Guide <a class="header-anchor" href="#upgrade-guide" aria-label="Permalink to &quot;Upgrade Guide&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This guide walks you through upgrading your UnoPim installation from <strong>v2.0.x to v2.1.0</strong>. This is a minor release within the same major version: it adds new features, performance improvements, and security hardening, but contains <strong>no breaking changes</strong> — no PHP or database engine bump, no Laravel framework upgrade, and no <code>bootstrap/app.php</code> rewrite.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Upgrading across a major version (for example <code>1.x → 2.x</code>)? Switch to the <strong>2.0.x</strong> documentation and follow its <a href="/2.0/prologue/upgrade-guide.html">Upgrade Guide</a>, which covers the Laravel 12 and PHP 8.3 migration. Once you are on v2.0.x, return here to move up to v2.1.0.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For the generic same-major update process (any <code>2.0.0 → 2.0.x</code> patch), see the <a href="./patch-update.html">Patch / Minor Update Guide</a>. This page is the version-specific guide for the <strong>v2.1.0</strong> release.</p></div><h2 id="pre-upgrade-checklist" tabindex="-1">Pre-upgrade Checklist <a class="header-anchor" href="#pre-upgrade-checklist" aria-label="Permalink to &quot;Pre-upgrade Checklist&quot;">​</a></h2><p>Before starting the upgrade, verify the following:</p><ul><li>[ ] You are currently running <strong>UnoPim v2.0.x</strong> (check the version in <code>composer.json</code> or the admin panel footer)</li><li>[ ] <strong>PHP 8.3+</strong>, <strong>Composer 2.x</strong>, and <strong>Node.js 18+</strong> are installed (requirements are unchanged from v2.0.0)</li><li>[ ] You have a complete backup of your database</li><li>[ ] You have a complete backup of your project files (especially <code>.env</code>, <code>storage/</code>, and any custom packages)</li><li>[ ] All queue workers, cron jobs, and Supervisor processes are stopped</li><li>[ ] You have reviewed the <strong>New in v2.1.0</strong> section below</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If you are still on <strong>v1.0.0</strong>, do not use this guide. Complete the <a href="/2.0/prologue/upgrade-guide.html">v1.x → v2.0.0 upgrade</a> first, then return here to upgrade to v2.1.0.</p></div><h2 id="upgrade-steps" tabindex="-1">Upgrade Steps <a class="header-anchor" href="#upgrade-steps" aria-label="Permalink to &quot;Upgrade Steps&quot;">​</a></h2><h3 id="_1-backup-your-system" tabindex="-1">1. Backup Your System <a class="header-anchor" href="#_1-backup-your-system" aria-label="Permalink to &quot;1. Backup Your System&quot;">​</a></h3><p>Create a complete backup of your database and project files before proceeding.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Backup your database</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysqldump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your_db_user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your_db_name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim_v2.0_backup.sql</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Backup your project directory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -czf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim_v2.0_files_backup.tar.gz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/current/unopim</span></span></code></pre></div><h3 id="_2-stop-queue-workers-and-scheduler" tabindex="-1">2. Stop Queue Workers and Scheduler <a class="header-anchor" href="#_2-stop-queue-workers-and-scheduler" aria-label="Permalink to &quot;2. Stop Queue Workers and Scheduler&quot;">​</a></h3><p>Stop queue workers and the scheduler so they do not pick up jobs against a half-updated codebase.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If using Supervisor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> supervisorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim-worker</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or, if running queue:work directly, stop the process (Ctrl+C)</span></span></code></pre></div><h3 id="_3-download-unopim-v2-1-0" tabindex="-1">3. Download UnoPim v2.1.0 <a class="header-anchor" href="#_3-download-unopim-v2-1-0" aria-label="Permalink to &quot;3. Download UnoPim v2.1.0&quot;">​</a></h3><p>Download the new release from one of these sources:</p><ul><li><a href="https://github.com/unopim/unopim/releases/tag/v2.1.0" target="_blank" rel="noreferrer">GitHub Release v2.1.0</a></li><li><a href="https://unopim.com/download" target="_blank" rel="noreferrer">Official Website</a></li></ul><p>If you track UnoPim with Git, fetch and check out the tag instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tags</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v2.1.0</span></span></code></pre></div><h3 id="_4-update-dependencies" tabindex="-1">4. Update Dependencies <a class="header-anchor" href="#_4-update-dependencies" aria-label="Permalink to &quot;4. Update Dependencies&quot;">​</a></h3><p>Install the updated PHP and frontend dependencies, then rebuild assets:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/unopim</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install PHP dependencies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install frontend dependencies and build assets</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>v2.1.0 bumps a few dependencies — <code>phpseclib/phpseclib</code> to <code>3.0.52</code> and <code>phpoffice/phpspreadsheet</code> to <code>1.30.4</code>. <code>composer install</code> applies these automatically.</p><h3 id="_5-run-database-migrations" tabindex="-1">5. Run Database Migrations <a class="header-anchor" href="#_5-run-database-migrations" aria-label="Permalink to &quot;5. Run Database Migrations&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span></code></pre></div><p>v2.1.0 ships schema migrations focused on <strong>query performance</strong>. No tables are dropped and no data is modified:</p><table tabindex="0"><thead><tr><th>Change</th><th>Purpose</th></tr></thead><tbody><tr><td>Index on <code>channels.code</code></td><td>Faster channel lookups by code</td></tr><tr><td>Index on <code>locales.status</code></td><td>Faster filtering of active locales</td></tr><tr><td>Index on <code>currencies.status</code></td><td>Faster filtering of active currencies</td></tr><tr><td>Composite index on <code>core_config (code, channel_code, locale_code)</code></td><td>Faster configuration resolution</td></tr><tr><td><code>webhook_logs.user_id</code> made nullable</td><td>Supports system-triggered webhooks with no associated user</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The <code>add_tone_to_magic_ai_prompts_table</code> migration now includes a proper <code>down()</code> method, so it can be rolled back cleanly if needed.</p></div><h3 id="_6-clear-cache-and-optimize" tabindex="-1">6. Clear Cache and Optimize <a class="header-anchor" href="#_6-clear-cache-and-optimize" aria-label="Permalink to &quot;6. Clear Cache and Optimize&quot;">​</a></h3><p>Clear all cached configurations and regenerate the storage link:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimize:clear</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> storage:link</span></span></code></pre></div><h3 id="_7-update-environment-configuration-optional" tabindex="-1">7. Update Environment Configuration (Optional) <a class="header-anchor" href="#_7-update-environment-configuration-optional" aria-label="Permalink to &quot;7. Update Environment Configuration (Optional)&quot;">​</a></h3><p>v2.1.0 adds an optional <strong>IP-based debug filter</strong>. When <code>APP_DEBUG</code> is enabled, you can restrict detailed error pages to specific IP addresses by adding <code>APP_DEBUG_ALLOWED_IPS</code> to your <code>.env</code>:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">APP_DEBUG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">APP_DEBUG_ALLOWED_IPS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=127.0.0.1,203.0.113.10</span></span></code></pre></div><p>If <code>APP_DEBUG_ALLOWED_IPS</code> is empty or omitted, behaviour is unchanged. Leaving it set in production lets you keep debugging enabled for your own IP while everyone else sees a generic error page.</p><h3 id="_8-restart-queue-workers-and-services" tabindex="-1">8. Restart Queue Workers and Services <a class="header-anchor" href="#_8-restart-queue-workers-and-services" aria-label="Permalink to &quot;8. Restart Queue Workers and Services&quot;">​</a></h3><p>v2.1.0 moves two heavy operations onto the queue, so a running worker is now more important than before:</p><ul><li><strong><code>SendProductWebhook</code></strong> — product webhooks are dispatched asynchronously instead of blocking the save request.</li><li><strong><code>ImportProductsJob</code></strong> — product imports run as a queued job, enabling reliable imports of 10,000+ products.</li></ul><p>Both jobs use UnoPim&#39;s existing queues, so no change to your <code>queue:work</code> command is required — just make sure a worker is running:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;system,completeness,default&quot;</span></span></code></pre></div><p>If you use <strong>Supervisor</strong>, restart the worker:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> supervisorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reread</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> supervisorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> supervisorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim-worker</span></span></code></pre></div><p>Then restart your web server and PHP-FPM:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If using Nginx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If using Apache</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apache2</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If using PHP-FPM</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> php8.3-fpm</span></span></code></pre></div><h2 id="new-in-v2-1-0" tabindex="-1">New in v2.1.0 <a class="header-anchor" href="#new-in-v2-1-0" aria-label="Permalink to &quot;New in v2.1.0&quot;">​</a></h2><p>v2.1.0 is a feature and hardening release. Highlights:</p><h3 id="ai-magicai" tabindex="-1">AI &amp; MagicAI <a class="header-anchor" href="#ai-magicai" aria-label="Permalink to &quot;AI &amp; MagicAI&quot;">​</a></h3><ul><li><strong>ManageAssociations AI Agent tool</strong> — manage product associations (related, cross-sell, up-sell) through natural language, with clickable product links in the responses.</li><li><strong>MagicAI Custom Provider</strong> — connect any OpenAI-compatible endpoint through a hardened adapter.</li><li><strong>MagicAI ModelRecommender</strong> — filters out non-chat model families when fetching the model list, so only compatible models are suggested.</li><li><strong>PrismErrorResolver</strong> — translates raw AI provider errors into clear, user-friendly messages.</li></ul><h3 id="performance-data-processing" tabindex="-1">Performance &amp; Data Processing <a class="header-anchor" href="#performance-data-processing" aria-label="Permalink to &quot;Performance &amp; Data Processing&quot;">​</a></h3><ul><li><strong>Async product webhooks</strong> — the <code>SendProductWebhook</code> job keeps product save requests fast.</li><li><strong>Queued product imports</strong> — the <code>ImportProductsJob</code> job makes large imports reliable.</li><li><strong>New database indexes</strong> — faster channel, locale, currency, and configuration lookups.</li></ul><h3 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h3><ul><li><strong>Production-ready Docker setup</strong> — a multi-container stack (Nginx + PHP-FPM) with healthchecks, Redis, Elasticsearch, Mailpit, and OPcache tuning.</li><li><strong>Demo data seeding</strong> — install sample catalog data with the <code>--with-demo-data</code> flag during installation, or via the standalone seeding command, for faster onboarding.</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><strong><code>clean_content()</code> helper</strong> — XSS sanitisation of user-generated content via HTMLPurifier.</li><li><strong>IP-based debug filtering</strong> — restrict detailed error output with <code>APP_DEBUG_ALLOWED_IPS</code>.</li><li>Fixes for 5 reported vulnerabilities and expanded automated test coverage.</li></ul><h3 id="dashboard-ux" tabindex="-1">Dashboard &amp; UX <a class="header-anchor" href="#dashboard-ux" aria-label="Permalink to &quot;Dashboard &amp; UX&quot;">​</a></h3><ul><li><strong>Clickable dashboard product stats</strong> — the dashboard product counters now act as filter chips that link straight to the filtered product grid.</li></ul><p>For a complete and detailed list of all changes, please visit the <a href="https://github.com/unopim/unopim/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">UnoPim CHANGELOG on GitHub</a>.</p><h2 id="post-upgrade-steps" tabindex="-1">Post-upgrade Steps <a class="header-anchor" href="#post-upgrade-steps" aria-label="Permalink to &quot;Post-upgrade Steps&quot;">​</a></h2><p>After completing all upgrade steps, verify your installation:</p><ol><li><strong>Test core functionalities</strong> — Log in to the admin panel, browse products, categories, and attributes to ensure everything loads correctly.</li><li><strong>Check error logs</strong> — Review <code>storage/logs/laravel.log</code> for any errors or deprecation warnings.</li><li><strong>Verify queue processing</strong> — Ensure queue workers are running and confirm that the new <code>SendProductWebhook</code> and <code>ImportProductsJob</code> jobs are processed.</li><li><strong>Test product webhooks</strong> — If you use webhooks, save a product and confirm the webhook is delivered asynchronously.</li><li><strong>Test product import</strong> — Run a product import and confirm it completes through the queued <code>ImportProductsJob</code>.</li><li><strong>Test custom packages</strong> — If you have custom packages or integrations, verify they still work as expected.</li><li><strong>Re-index Elasticsearch</strong> — If you use Elasticsearch, re-index your data to ensure search results are accurate.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim:product:index</span></span></code></pre></div><h2 id="need-help" tabindex="-1">Need Help? <a class="header-anchor" href="#need-help" aria-label="Permalink to &quot;Need Help?&quot;">​</a></h2><ul><li><a href="https://docs.unopim.com" target="_blank" rel="noreferrer">UnoPim Documentation</a></li><li><a href="https://github.com/unopim/unopim/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li>Contact support at <a href="mailto:support@webkul.in" target="_blank" rel="noreferrer">support@webkul.in</a></li></ul>`,65)])])}const g=s(n,[["render",o]]);export{u as __pageData,g as default};
